forcedColors:
@media (forced-colors: active) {
  :root {
    --jt-canvas: Canvas;
    --jt-surface: Canvas;
    --jt-surface-soft: Canvas;
    --jt-text: CanvasText;
    --jt-text-muted: GrayText;
    --jt-text-subtle: GrayText;
    --jt-accent: Highlight;
    --jt-accent-hover: Highlight;
    --jt-accent-ui: Highlight;
    --jt-on-accent: CanvasText;
    --jt-border: GrayText;
  }
}

wideGamut:
@supports (color: color(display-p3 0 0 0)) {
  :root {
    --jt-canvas: color(display-p3 0.7499 1.0000 1.0000);
    --jt-surface: color(display-p3 0.7242 1.0000 0.9755);
    --jt-surface-soft: color(display-p3 0.7113 1.0000 0.9624);
    --jt-text: color(display-p3 0.0000 0.1156 0.1505);
    --jt-text-muted: color(display-p3 0.0590 0.3227 0.3581);
    --jt-accent: color(display-p3 0.0900 0.3448 0.3802);
    --jt-accent-hover: color(display-p3 0.0000 0.2580 0.2931);
    --jt-on-accent: color(display-p3 0.7242 1.0000 0.9755);
  }
}

full:
:root {
  --jt-canvas: #e7fefa;
  --jt-surface: #cefdf5;
  --jt-surface-soft: #c0fdf3;
  --jt-text: #021a1d;
  --jt-text-muted: #0f5158;
  --jt-text-subtle: #08717a;
  --jt-accent: #17575d;
  --jt-accent-hover: #0c4045;
  --jt-accent-ui: #08717a;
  --jt-on-accent: #cefdf5;
  --jt-border: #08717a;
}

@media (prefers-color-scheme: dark) {
  :root {
    --jt-canvas: #000000;
    --jt-surface: #000000;
    --jt-surface-soft: #000000;
    --jt-text: #78ced7;
    --jt-text-muted: #368f98;
